  "WILD расширяется на барабан": "WILD expands across the reel",
  "выигравшие символы исчезают, остальные падают": "winning symbols disappear and the rest fall down",
  "WILD остаются на следующих вращениях": "WILDs remain for subsequent spins",
  "монеты закрепляются на двух бесплатных повторных вращениях": "coins lock in place for two free respins",
  "сборщики суммируют монеты": "collectors add up coins",
  "оплачиваются соседние группы от пяти символов": "adjacent groups of five or more symbols pay out",
  "совпадения считаются слева направо по всем способам": "matches count from left to right across all ways",
  "выбранный первым символом знак расширяется при появлении на трёх барабанах": "the symbol chosen by the first symbol expands when it appears on three reels",
  "бонусная WILD-колонна движется влево": "the bonus WILD column moves left",
  "от двух до пяти барабанов синхронизируются": "two to five reels synchronise",
  "все тайные символы раскрываются одним знаком": "all mystery symbols reveal the same symbol",
  "WILD усиливает выигрышную линию": "WILD boosts the winning payline",
  "ячейки усиливают соседние группы": "cells boost adjacent groups",
  "бонусные колёса дают дополнительные награды": "bonus wheels give extra rewards",
  "WILD-луч превращает свой барабан": "the WILD beam transforms its reel",
  "монеты и этап бонуса усиливают выплату": "coins and bonus stages boost the payout",
  "желанные символы остаются на бесплатных вращениях": "wish symbols stay during free spins",
  "монеты усиливают выплату каскада": "coins boost the cascade payout",
  "{0}×{1}. {2}. {3}Линии оплачиваются от трёх совпадений, группы от пяти, россыпь от восьми. WILD заменяет обычные знаки в линиях и способах. Бонус содержит максимум два бесплатных этапа, без продления. Наша самостоятельная математика: расчётный возврат 98% до округления; каждая награда округляется вниз до 0,01 монеты.": "{0}×{1}. {2}. {3}Paylines pay from three matches, groups from five, and scatter matches from eight. WILD substitutes for regular symbols in paylines and ways. The bonus contains at most two free stages, with no extension. Our original maths: theoretical return 98% before rounding; each reward rounds down to 0.01 coin.",
  "Дискретная серия до {0} этапов. На каждом скрытый бросок должен достичь {1} из шести. После первого успеха можно забрать выплату. Ошибка теряет ставку, последний этап оплачивается автоматически. Возврат 98% до округления.": "A discrete series of up to {0} stages. At each stage, a hidden roll must reach {1} out of six. Cash out after the first success. A miss loses the stake; the final stage pays automatically. Return 98% before rounding.",
  "Шестнадцать ячеек и четыре скрытые ловушки. Забери выплату после первой безопасной ячейки; шестая оплачивается автоматически. Возврат 98% до округления.": "Sixteen cells and four hidden traps. Cash out after the first safe cell; the sixth pays automatically. Return 98% before rounding.",
  "{0}. Ставка и выплата проходят через общий тестовый кошелёк. Возврат 98% до округления.": "{0}. The stake and payout go through the shared test wallet. Return 98% before rounding.",
  "Полностью WILD-цепочка оплачивается отдельно. Более короткая WILD-цепочка может дать дополнительную награду рядом с более длинной обычной комбинацией.": "An all-WILD chain pays separately. A shorter WILD chain may give an extra reward alongside a longer regular combination.",
