  "Займи место и играй клавишами или касаниями. Музыку слышит весь зал. Звук рояля регулируется в настройках игрока.": "Take a seat and play with the keys or touch. The whole hall hears the music. Adjust piano volume in player settings.",
  "Забей 7 голов. Управляй битой мышью, пальцем или стрелками, каждый на своей половине.": "Score 7 goals. Move your paddle with the mouse, touch or arrows, each on your own half.",
  "Американский пул «8». Сначала забей свои сплошные или полосатые шары, затем восьмёрку в выбранную лузу. Ранняя восьмёрка или фол на ней означают поражение.": "American 8-ball pool. Pot your solids or stripes first, then the eight ball in your chosen pocket. Potting the eight ball early or fouling on it loses the game.",
  "A W S E D F T G Y H U J K O L P ; · одновременно до 8 нот": "A W S E D F T G Y H U J K O L P ; · up to 8 notes at once",
  "Прицелься мышью или стрелками. Зажми пробел для набора силы, отпусти для удара. Можно также выбрать силу ползунком и нажать «Ударить».": "Aim with the mouse or arrows. Hold Space to build power, release to shoot. You can also set power with the slider and press Shoot.",
