  "Обновить": "Refresh",
  "Правила, символы и каскады": "Rules, symbols and cascades",
  "От восьми одинаковых обычных знаков в любой части поля дают выплату. Знаки могут стоять отдельно друг от друга. После совпадения они исчезают, оставшиеся падают вниз, сверху приходят новые. Раунд содержит основной спин и максимум два бесплатных каскада. Каскад без совпадений завершает раунд раньше. Накопленное начисляется после окончания всего раунда.": "Eight or more matching regular symbols anywhere on the board pay out. Symbols do not need to be adjacent. Matching symbols disappear; the rest fall down and new ones arrive from above. A round includes the base spin and at most two free cascades. A cascade with no matches ends the round early. Accumulated winnings are credited when the entire round ends.",
  "Базовые множители в таблице показаны": "Base multipliers in the table are shown",
  ". Ставка указана за весь раунд. Множитель включает ставку. Каждая выплата округляется вниз до 0,01 монеты, затем выплаты суммируются. «Проверить ход» подтверждает прежнюю операцию.": ". The stake covers the whole round. Multipliers include the stake. Each payout rounds down to 0.01 coin, then payouts are added together. Check move confirms the previous operation.",
  "Игра на тестовые монеты клуба": "Play with club test coins",
  "Сладкие совпадения. Новые каскады.": "Sweet matches. Fresh cascades.",
  "Созвездия совпадений и светящиеся сферы": "Constellations of matches and glowing orbs",
  "Карамельные монеты остаются на поле и не имеют отдельной выплаты.": "Caramel coins remain on the board and have no separate payout.",
  "Сферы остаются на поле, падают вместе с другими знаками и усиливают каждую совпавшую группу текущего этапа. Множитель равен одному плюс число сфер во всём текущем поле. Он уже включён в показанные выплаты и не умножает ставку отдельно.": "Orbs remain on the board, fall with other symbols and boost each matching group in the current stage. The multiplier is one plus the number of orbs on the entire current board. It is already included in displayed payouts and does not multiply the stake separately.",
