  "Коэффициент выплат: 99% от обратной вероятности успеха. Начисление округляется вниз до сотой демомонеты или миллионной USDT. Закрытие окна сохраняет активную партию.": "Payout factor: 99% of the inverse success probability. Credits round down to one hundredth of a demo coin or one millionth of a USDT. Closing the window preserves the active game.",
