  "Забрать": "Cash out",
  "Начать партию": "Start game",
  "Угадай, будет следующая карта выше или ниже. Туз имеет ранг 1. Одинаковые ранги проигрывают. Карты тянутся независимо. После первого удачного хода можно забрать выигрыш; после двух он начисляется автоматически.": "Guess whether the next card will be higher or lower. Ace has rank 1. Equal ranks lose. Cards are drawn independently. Cash out after the first successful move; after two, winnings are credited automatically.",
  "Поднимайся по девяти уровням. На каждом одна клетка с драконом, остальные выигрышные. После удачного выбора можно забрать выплату. Дракон завершает партию с потерей ставки; девятый уровень выплачивается автоматически.": "Climb nine levels. Each has one dragon cell; the others win. Cash out after a successful choice. A dragon ends the game and loses the stake; the ninth level pays automatically.",
