  "Шесть барабанов,": "Six reels,",
  "рядов": "rows",
  "Собери светлую комбинацию": "Build a glowing combination",
  "Соседи по стороне": "Orthogonal neighbours",
  "Группы от пяти знаков": "Groups of five or more symbols",
  "Выплаты групп и сборщиков": "Group and collector payouts",
  "Правила, символы и группы": "Rules, symbols and groups",
  "Группа содержит минимум пять одинаковых символов, соседних по стороне. Диагонали не соединяются. Отдельные группы одного знака оплачиваются отдельно.": "A group contains at least five matching symbols sharing an edge. Diagonals do not connect. Separate groups of the same symbol pay separately.",
  "Три бонусных знака на основном поле открывают два новых бесплатных вращения без продления. Символы не закрепляются и не исчезают; каждый этап получает новую сетку. Начисление приходит после всего раунда.": "Three bonus symbols on the base board unlock two new free spins with no extension. Symbols do not lock or disappear; each stage receives a fresh grid. Winnings are credited after the entire round.",
  "Ставка за весь раунд. Каждая награда округляется вниз до 0,01 монеты, затем суммы складываются. «Проверить ход» подтверждает прежнюю операцию. Сохранённые этапы можно посмотреть без новой ставки.": "The stake covers the whole round. Each reward rounds down to 0.01 coin, then amounts are added. Check move confirms the previous operation. Saved stages can be viewed without another stake.",
  "Светящиеся семена и волшебные фонари": "Glowing seeds and magic lanterns",
  "Грани соединяются. Сила складывается.": "Facets connect. Power adds up.",
  "Два фонаря собирают светящиеся семена": "Two lanterns collect glowing seeds",
  "Сила группы складывается из её ячеек": "Group power is the sum of its cells",
  "Каждый из первых двух фонарей по порядку ячеек собирает все текущие семена. Семена остаются на поле. Их сила 2..5 зависит от ячейки и не является денежной суммой.": "Each of the first two lanterns in cell order collects all current seeds. Seeds stay on the board. Their power of 2..5 depends on the cell and is not a monetary amount.",
  "Сила каждой ячейки 1..3 зависит от её позиции и этапа. Сила группы равна сумме её ячеек и уже учтена в показанной выплате.": "Each cell's power of 1..3 depends on its position and stage. Group power equals the sum of its cells and is already included in the displayed payout.",
  "Таблица обычных групп. Награды фонарей показаны отдельно под полем.": "Regular group paytable. Lantern rewards appear separately below the board.",
  "Таблица базовых групп при силе каждой ячейки 1. Реальная сумма сил усиливает награду; показанная под полем выплата уже учитывает это усиление.": "Base group paytable with cell power 1. The actual sum of powers boosts the reward; the payout shown below the board already includes this boost.",
