  "SCATTER: штурвал": "SCATTER: ship's wheel",
  "Парус": "Sail",
  "Огонь и молния. Сила каждой линии.": "Fire and lightning. Power in every payline.",
  "Один ключ. Три колонны открывают шифр.": "One key. Three columns unlock the cipher.",
  "Луч маяка ведёт вверх и вниз.": "The lighthouse beam leads up and down.",
  "Любой WILD раскрывается на всю свою колонну. В оплаченной цепочке WILD усиливают именно эту линию: 2×, 3× или 4×. WILD не закрепляется на следующем вращении.": "Any WILD expands across its entire column. In a paid chain, WILDs boost that specific payline by 2×, 3× or 4×. WILD does not stay for the next spin.",
  "Ключом становится исходная верхняя левая Лазурная печать, Шафрановое перо или Алый свиток. При другом знаке ключом становится Лазурная печать. Если ключ встречается в трёх разных колоннах, каждая такая колонна целиком превращается в WILD. Ключ определяется заново на каждом этапе, выбора игрока нет.": "The key is the original top-left Azure seal, Saffron feather or Scarlet scroll. Any other symbol defaults to Azure seal. If the key appears in three different columns, each such column becomes entirely WILD. The key is determined anew at each stage; the player does not choose it.",
  "Луч создаёт только WILD в средней строке. Он раскрывается вверх и вниз на всю свою колонну. WILD сверху или снизу заменяет знак, но луч не запускает.": "Only a WILD in the middle row creates a beam. It expands up and down across its entire column. A WILD at the top or bottom substitutes for a symbol but does not trigger a beam.",
  "ЛИНИЙ": "PAYLINES",
  "КЛЮЧ ЭТАПА": "STAGE KEY",
  "Раскроется после остановки": "Revealed after stopping",
  "Новый ключ на каждом вращении": "A new key on every spin",
  "Пять барабанов, три ряда": "Five reels, three rows",
  "Все линии активны": "All paylines active",
  "WILD заменяет знаки": "WILD substitutes for symbols",
  "Выплаты линий": "Payline payouts",
  "Правила, символы и линии": "Rules, symbols and paylines",
  "Три SCATTER на итоговом поле после преобразования открывают ровно два бесплатных новых вращения без новой ставки. В них нет каскадов, закреплений или продления. Накопленное начисляется после завершения всего раунда.": "Three SCATTERs on the final board after transformation unlock exactly two new free spins with no new stake. No cascades, locked symbols or extensions occur in them. Accumulated winnings are credited after the entire round.",
  "Базовые награды за одну линию, до усиления WILD. Выбирается одна лучшая цепочка слева от трёх символов. Отдельной оплаты WILD или декоративного знака нет.": "Base rewards per payline, before WILD boosts. One best chain of at least three symbols is selected from the left. No separate payout for WILD or decorative symbols.",
  "Ставка указана за все линии и весь раунд. Множитель включает ставку. Каждая выплата округляется вниз до 0,01 монеты, затем выплаты суммируются. «Проверить ход» подтверждает прежнюю операцию. Сохранённые этапы можно посмотреть без новой ставки.": "The stake covers all paylines and the entire round. Multipliers include the stake. Each payout rounds down to 0.01 coin, then payouts are added. Check move confirms the previous operation. Saved stages can be viewed without another stake.",
  "Огонь и молния раскрывают WILD": "Fire and lightning reveal WILD",
  "Ключ должен встретиться в трёх колоннах": "The key must appear in three columns",
  "Луч начинается только в средней строке": "The beam starts only in the middle row",
  "Показываем событие этого вращения…": "Showing this spin's event…",
