  "Звук и музыка": "Sound and music",
  "Управление столом": "Table controls",
  "Набери до 21 очка. Туз даёт 1 или 11. Дилер берёт карты до 17, включая остановку на мягких 17. Блэкджек возвращает 2,5 ставки, обычный выигрыш 2 ставки, ничья возвращает ставку. Одна колода, без split и double.": "Get up to 21 points. Ace counts as 1 or 11. The dealer draws to 17 and stands on soft 17. Blackjack returns 2.5 stakes, regular wins 2 stakes, ties return the stake. One deck, no split or double.",
  "Учебный холдем против бота. По две личные карты, пять общих. Сравниваются лучшие пять карт. Бот всегда уравнивает. На каждой улице можно продолжить, повысить ставку или сделать пас. При ничьей банк делится поровну.": "Practice Hold'em against a bot. Two hole cards each and five community cards. Best five-card hands are compared. The bot always calls. On each street, continue, raise or fold. Ties split the pot equally.",
  "Колода из 53 карт с одним джокером. Удержи нужные карты и один раз замени остальные. Джокер заменяет любую карту. Множители: две пары 1, тройка 2, стрит 4, флеш 5, фулл-хаус 8, каре 20, стрит-флеш 40, роял-флеш 100, пять одинаковых 250. Одна пара не оплачивается.": "A 53-card deck with one joker. Hold the cards you want and replace the rest once. Joker is wild. Multipliers: two pair 1, three of a kind 2, straight 4, flush 5, full house 8, four of a kind 20, straight flush 40, royal flush 100, five of a kind 250. One pair does not pay.",
  "Выбери игрока, банкира или ничью. Очки считаются по последней цифре суммы: туз 1, десятки и картинки 0. Добор карт выполняется автоматически. Игрок возвращает 2 ставки, банкир 1,95, ничья 9. При ничьей ставки на игрока и банкира возвращаются.": "Choose Player, Banker or Tie. Scores use the last digit of the total: ace 1, tens and face cards 0. Additional cards are drawn automatically. Player returns 2 stakes, Banker 1.95, Tie 9. On a tie, Player and Banker bets are returned.",
  "Pass Line: первый бросок 7/11 выигрывает, 2/3/12 проигрывает. Иначе устанавливается цель: повтор цели выигрывает, 7 проигрывает. Field: один бросок, 3/4/9/10/11 дают полный возврат ×2, 2 даёт ×3, 12 даёт ×4. Any Seven: 7 даёт ×5, прочие числа проигрывают.": "Pass Line: an opening 7/11 wins, 2/3/12 loses. Otherwise a point is set: repeating it wins, 7 loses. Field: one roll; 3/4/9/10/11 return ×2, 2 returns ×3, 12 returns ×4. Any Seven: 7 returns ×5, other totals lose.",
