  "Настройки разговора": "Conversation settings",
  "Мира помнит разговоры в твоём аккаунте. «Начать заново» очищает её память. Реплики передаются codex.sale. Не сообщай секреты. Мира не заменяет психолога.": "Mira remembers conversations in your account. Start over clears her memory. Messages are sent to codex.sale. Do not share secrets. Mira is not a substitute for a psychologist.",
