  "Ставка за спин": "Stake per spin",
  "Пять активных линий": "Five active paylines",
  "Выигрышные линии": "Winning paylines",
  "Ставка оплачивает все пять линий. Три одинаковых обычных знака слева направо дают выплату. WILD заменяет обычный знак; на каждой линии оплачивается лучшая комбинация. Звезда и монета в этом слоте не дают отдельной выплаты. Бонусных ходов нет.": "The stake covers all five paylines. Three matching regular symbols from left to right pay out. WILD substitutes for a regular symbol; the best combination pays on each line. Star and coin have no separate payout in this slot. No bonus moves.",
  "Множитель включает ставку. Каждая выплата округляется вниз до 0,01 монеты, затем выплаты линий суммируются. Результат и баланс сохраняются на сервере. «Проверить ход» подтверждает прежнюю операцию без новой ставки.": "Multipliers include the stake. Each payout rounds down to 0.01 coin, then payline payouts are added. Results and balance are saved on the server. Check move confirms the previous operation without a new stake.",
  "Ответ ещё не подтверждён. «Проверить ход» продолжит ту же операцию.": "The response is not confirmed yet. Check move continues the same operation.",
  "Барабаны вращаются. Ждём подтверждение спина…": "Reels spinning. Awaiting spin confirmation…",
