  "Выдели адрес в поле и скопируй его вручную.": "Select the address in the field and copy it manually.",
  "Проверяем тестовый баланс…": "Checking test balance…",
  "Пополняй баланс тестовыми USDT в сети Nile. Поступления зачисляются автоматически после подтверждения. Токены бесплатны, вывод недоступен.": "Top up with test USDT on Nile. Deposits are credited automatically after confirmation. Tokens are free; withdrawals are unavailable.",
  "Нажми «Получить адрес пополнения» и отправь на него тестовый USDT из сети Nile.": "Press Get deposit address and send test USDT from the Nile network to it.",
