  "Тестовый кошелёк пока не подключён.": "Test wallet not connected yet.",
  "Обновлено:": "Updated:",
  "Подтверждённых поступлений пока нет.": "No confirmed deposits yet.",
  "Баланс подтверждён. Показаны последние 50 поступлений.": "Balance confirmed. Showing the latest 50 deposits.",
  "Не удалось загрузить тестовый кошелёк.": "Could not load the test wallet.",
  "Выбери сторону. Брось вызов удаче.": "Choose a side. Challenge your luck.",
  "Выпадает число от 0,00 до 99,99. «Меньше» выигрывает при результате строго ниже порога, «Не меньше» при результате равном порогу или выше. Порог меняет шанс и множитель.": "The result is a number from 0.00 to 99.99. Under wins strictly below the threshold; At least wins at or above it. The threshold changes the chance and multiplier.",
  "Открывай камни. Забирай вовремя.": "Reveal gems. Cash out in time.",
  "На поле 25 клеток скрыты мины. Каждый безопасный камень увеличивает множитель. После первого камня можно забрать выплату. Попадание на мину завершает партию без выплаты. Закрытие окна сохраняет активную партию.": "Mines are hidden in a 25-cell board. Each safe gem increases the multiplier. Cash out after the first gem. Hitting a mine ends the game without a payout. Closing the window preserves the active game.",
  "Один шар. Множество путей.": "One ball. Many paths.",
  "На каждом ряду шар идёт влево или вправо с равными шансами. Начисление зависит от конечного кармана. Риск меняет выплаты, количество рядов меняет распределение результатов.": "At each row the ball goes left or right with equal chances. The payout depends on the final pocket. Risk changes payouts; the number of rows changes the result distribution.",
  "Назначь цель. Поймай множитель.": "Set a target. Catch the multiplier.",
  "Задай целевой множитель до ставки. Если выпавший множитель достигнет цели, начисление равно ставке, умноженной на цель. Чем выше цель, тем меньше вероятность выигрыша.": "Set your target multiplier before betting. If the drawn multiplier reaches it, the payout is the stake times the target. A higher target means a lower win probability.",
  "Твои числа. Десять возможностей.": "Your numbers. Ten chances.",
  "Выбери от 1 до 10 чисел из 40. Сервер вытягивает 10 разных чисел. Выплата определяется количеством совпадений и выбранным риском. Таблица показывает полное начисление, включая возврат ставки.": "Choose 1 to 10 numbers from 40. The server draws 10 different numbers. Payout depends on matches and selected risk. The table shows the full credit, including the stake return.",
