  "WILD заменяет обычные символы.": "WILD substitutes for regular symbols.",
  "Выплаты всех линий, способов и групп суммируются. Точную выплату бонусов показывает список под полем.": "All payline, ways and group payouts are added together. The list below the board shows exact bonus payouts.",
