  "Базовая выплата за совпадения в поле, до собранных множителей.": "Base payout for board matches, before collected multipliers.",
  "Схемы выигрышных линий": "Winning payline layouts",
  "Ставка указана за весь раунд. Бонусные ходы продолжат ту же партию без нового списания. Множитель включает ставку; каждая выплата округляется вниз до 0,01 монеты.": "The stake covers the entire round. Bonus moves continue the same game without another debit. Multipliers include the stake; each payout rounds down to 0.01 coin.",
  "Результат и баланс сохраняются на сервере. При потере ответа «Проверить ход» подтвердит ту же операцию.": "Results and balances are saved on the server. If a response is lost, Check move confirms the same operation.",
