  "ряда": "rows",
  "Три бонусных знака открывают два бесплатных этапа без новой ставки. Накопленное начисляется после завершения всего раунда.": "Three bonus symbols unlock two free stages without a new stake. Accumulated winnings are credited after the entire round.",
  "Портал WILD открывает новые горизонты": "The WILD portal opens new horizons",
  "Закрепляй короны. Усиливай свои линии.": "Lock crowns. Boost your paylines.",
  "WILD раскрывается на весь барабан": "WILD expands across the entire reel",
  "Короны WILD усиливают выигрышные линии": "WILD crowns boost winning paylines",
  "WILD заменяет обычные символы и раскрывается на весь свой барабан после остановки.": "WILD substitutes for regular symbols and expands across its entire reel after stopping.",
  "Короны WILD заменяют обычные символы. На оплаченной цепочке они дают множитель 2×, 3× или 4× по числу WILD, максимум 4×. В бесплатных этапах короны остаются на своих местах.": "WILD crowns substitute for regular symbols. In a paid chain, they apply a multiplier of 2×, 3× or 4× according to the number of WILDs, capped at 4×. Crowns stay in place during free stages.",
  "WILD раскрывает свою силу…": "WILD reveals its power…",
