  "Закреплено корон: {0}": "Crowns locked: {0}",
  "Восстановить полёт": "Restore flight",
  "Подтверждённые ставки": "Confirmed bets",
  "Множитель показывает полное начисление, включая возврат ставки. Показанная возможная выплата ещё не является начислением. Выплата округляется вниз до сотой монеты. Это игры на виртуальные монеты.": "The multiplier shows the full credit, including the stake return. A displayed potential payout is not yet credited. Payouts round down to one hundredth of a coin. These games use virtual coins.",
  "За пределы земного притяжения": "Beyond Earth's gravity",
  "Твой счастливый поворот": "Your lucky turn",
