  "ВОЗМОЖНОСТЬ НА КАЖДОМ ПОВОРОТЕ": "A CHANCE AT EVERY TURN",
  "Автоматически забрать при": "Auto cash out at",
  "Можешь забрать раньше вручную. Если полёт закончится первым, ставка сгорает.": "You can cash out manually earlier. If the flight ends first, the stake is lost.",
  "Уровень риска": "Risk level",
  "Секторов": "Segments",
  "Начать полёт": "Start flight",
  "Вращать колесо": "Spin wheel",
  "Окно можно закрыть. Полёт продолжится, сервер заберёт выплату на выбранной цели, если полёт её достигнет.": "You can close the window. The flight continues; the server cashes out at your selected target if the flight reaches it.",
  "Результат определяет сервер до анимации. Закрытие окна не отменяет ставку.": "The server determines the result before the animation. Closing the window does not cancel the bet.",
  "Таблица выплат": "Paytable",
  "Начисление и вероятность": "Credit and probability",
  "Множитель растёт во время полёта. Нажми «Забрать» до его завершения или выбери автоматическую цель от 1,10× до 100×. Успешное получение выигрыша подтверждает сервер. Множитель на экране показывает последнее подтверждённое состояние и обновляется примерно раз в секунду. При потере связи показания останавливаются, автоматическая цель сохраняется.": "The multiplier rises during the flight. Press Cash out before it ends, or set an automatic target from 1.10× to 100×. The server confirms successful payouts. The displayed multiplier shows the latest confirmed state and updates about once per second. On disconnection, the display pauses and your automatic target is kept.",
  "Колесо содержит 50 одинаковых по размеру секторов. Каждый сектор выпадает с вероятностью 2%. Риск меняет только таблицу выплат. Указатель всегда показывает сектор, выбранный сервером. Суммарный RTP для каждого риска равен 98%.": "The wheel has 50 equal-sized segments. Each has a 2% probability. Risk changes only the paytable. The pointer always shows the segment chosen by the server. Total RTP is 98% for every risk level.",
  "Проверить полёт": "Check flight",
