  "Зеркальце": "Hand mirror",
  "WILD: маска": "WILD: mask",
  "Камера": "Camera",
  "Вспышка": "Flash",
  "Алиса": "Alice",
  "Мия": "Mia",
  "Ева": "Eva",
  "Поле 6×5, 14 постоянных линий. От трёх одинаковых символов слева. WILD заменяет обычные символы, на каждой линии оплачивается лучшая комбинация с учётом множителя ячеек. Выигрышные символы падают каскадом. Вспышка на выигрышном поле заряжает свою ячейку для следующих каскадов до ×4. Линия получает наибольший множитель среди своих выигрышных ячеек. 3/4/5+ камер на конечном поле дают 8/10/12 бесплатных вращений. В фотосессии закрепляются до трёх WILD, множители ячеек сохраняются. Линия из закреплённых WILD оплачивается один раз за спин. Три камеры внутри бонуса добавляют два спина, максимум 20 за раунд. До 10 показов поля за спин. Общий предел выплаты 5000 ставок. Одна ставка и одна итоговая выплата. Героини и вторые образы открываются по прогрессу от суммы принятых ставок после завершения раунда. Альбом не меняет вероятности и выплаты. Только тестовые монеты.": "6×5 board, 14 fixed paylines. Matches of three or more from the left. WILD substitutes for regular symbols; each line pays its best combination with cell multipliers. Winning symbols cascade. A flash on a winning board charges its cell up to ×4 for subsequent cascades. A line uses the highest multiplier among its winning cells. 3/4/5+ cameras on the final board award 8/10/12 free spins. Up to three WILDs lock during the photo shoot and cell multipliers persist. An all-locked-WILD line pays once per spin. Three cameras inside the bonus add two spins, up to 20 per round. At most 10 board reveals per spin. Total payout cap: 5000 stakes. One stake and one final payout. Characters and second looks unlock through accepted-stake progress after the round ends. The album does not change probabilities or payouts. Test coins only.",
  "Легендарный": "Legendary",
  "Эпический": "Epic",
  "Редкий": "Rare",
  "8+ в любом месте · Билеты и фестиваль": "8+ anywhere · Tickets and festival",
