  "Волчок +10": "Spinner +10",
  "Поле 6×5. Восемь одинаковых конфет в любом месте дают выплату и каскад, до 20 каскадов. Волчки повышают энергию перед выплатой до ×50. Четыре билета на конечном поле открывают 10 бесплатных вращений; в фестивале три билета добавляют три, максимум 30. Покупка стоит 35 ставок, предел выплаты 5000 ставок. Одна ставка и одна итоговая выплата.": "6×5 board. Eight matching candies anywhere pay and cascade, up to 20 cascades. Spinners increase energy before payout, up to ×50. Four tickets on the final board unlock 10 free spins; during the festival, three tickets add three, capped at 30. Buying costs 35 stakes; payout cap 5000 stakes. One stake and one final payout.",
  "НОВЫЕ ИГРЫ · ЧЕТЫРЕ МИРА": "NEW GAMES · FOUR WORLDS",
  "ВНЕШНИЕ КАТАЛОГИ": "EXTERNAL CATALOGUES",
