  "Баррикада": "Barricade",
  "Собственные частоты символов и событий. Вероятности исходной игры не опубликованы.": "Original symbol and event frequencies. The source game's probabilities are not public.",
  "Таблица выплат, 14 линий и бонусы сверены с открытым меню velvet-0.3.": "Paytable, 14 paylines and bonuses checked against the public velvet-0.3 menu.",
