  "Звёздный хаос": "Star chaos",
  "Вторжение": "Invasion",
  "Дальнее эхо": "Distant echo",
  "Пять барабанов и двадцать фиксированных линий.": "Five reels and twenty fixed paylines.",
  "От трёх порталов начинаются 10, 12 или 15 бесплатных вращений.": "Three or more portals start 10, 12 or 15 free spins.",
  "Миссии сохраняют энергию до ×50; лучи расширяют WILD, эхо даёт второй этап.": "Missions keep energy up to ×50; beams expand WILD, echo adds a second stage.",
  "Двадцать рисунков линий и таблица выплат сверены с публичным меню.": "Twenty payline patterns and the paytable checked against the public menu.",
  "Продление по порталам не установлено публичным меню; новых вращений по ним не добавляем.": "Portal retriggers are not specified by the public menu, so no extra spins are added for them.",
  "Вероятности луча и второго этапа эха собственные. Эхо в дальней миссии случается вдвое чаще, а вероятность хотя бы одного луча во вторжении выше.": "Beam and second-stage echo probabilities are original. Echo occurs twice as often in the distant mission, and at least one beam is more likely during invasion.",
  "Гоночное колесо": "Racing wheel",
  "Шлем": "Helmet",
  "Спортивный руль": "Sports steering wheel",
  "Турбина": "Turbine",
  "Синий купе": "Blue coupe",
  "Оранжевый маслкар": "Orange muscle car",
  "WILD: шестерня": "WILD: gear",
  "Финишные флаги": "Finish flags",
  "Баллон нитро": "Nitro bottle",
  "Поле 6×5, 20 постоянных линий. От трёх одинаковых символов слева; WILD заменяет обычные символы. На каждой линии платится лучшая комбинация. Выигрышные символы исчезают каскадом, передача повышается для следующего каскада до ×5. Два баллона нитро, собранные на выигрышных полях, дают один бесплатный перезапуск поля при остановке серии в этом вращении. 3/4/5+ флагов на конечном поле дают 8/10/12 бесплатных вращений со второй передачи. В бесплатной гонке 3 флага добавляют 2 вращения, максимум 20 всего. До 12 показов поля за вращение, предел всего раунда 3000 ставок. Одна ставка за все линии и одна итоговая выплата. Только тестовые монеты.": "6×5 board, 20 fixed paylines. Three or more matching symbols from the left; WILD substitutes for regular symbols. Each line pays its best combination. Winning symbols cascade away; the gear rises for the next cascade, up to ×5. Two nitro bottles collected on winning boards give one free board restart when the sequence stops within that spin. 3/4/5+ flags on the final board award 8/10/12 free spins starting in second gear. During the free race, 3 flags add 2 spins, capped at 20 total. At most 12 board reveals per spin; total round cap 3000 stakes. One stake for all paylines and one final payout. Test coins only.",
  "Нитро-заезд": "Nitro Run",
  "14 линий · Фотосессия · Альбом героинь": "14 paylines · Photo shoot · Character album",
  "20 линий · Передачи · Нитро-рывок": "20 paylines · Gears · Nitro boost",
  "Каскады · Баррикады до ×7 · Эвакуация": "Cascades · Barricades up to ×7 · Evacuation",
  "Поле 6×5, 8+ одинаковых припасов в любом месте, до 20 каскадов. Каждая закреплённая баррикада добавляет +1 к множителю, максимум ×7. 3/4/5+ маяков на конечном поле дают 10/12/15 бесплатных вращений. В эвакуации баррикады сохраняются, 3 маяка добавляют 2 вращения, до 20 всего. Предел 5000 ставок. Одна ставка и одна итоговая выплата в тестовый кошелёк.": "6×5 board, 8+ matching supplies anywhere, up to 20 cascades. Each locked barricade adds +1 to the multiplier, capped at ×7. 3/4/5+ beacons on the final board award 10/12/15 free spins. Barricades persist during evacuation; 3 beacons add 2 spins, capped at 20 total. Cap 5000 stakes. One stake and one final payout to the test wallet.",
