  "СВЕТ. КАМЕРА. ТВОЯ КОЛЛЕКЦИЯ.": "LIGHTS. CAMERA. YOUR COLLECTION.",
  "14 ЛИНИЙ И ВСПЫШКИ": "14 PAYLINES AND FLASHES",
  "Выигрышные символы падают каскадом. Вспышки заряжают ячейки до ×4 для следующих комбинаций.": "Winning symbols cascade. Flashes charge cells up to ×4 for subsequent combinations.",
  "БОНУСНАЯ ФОТОСЕССИЯ": "BONUS PHOTO SHOOT",
  "Камеры дают бесплатные вращения. До трёх WILD закрепляются, заряд ячеек сохраняется.": "Cameras award free spins. Up to three WILDs lock; cell charges persist.",
  "ОТКРЫВАЙ ГЕРОИНЬ": "UNLOCK CHARACTERS",
  "Героини открываются по общему прогрессу. Второй образ каждой героини открывается за игру с ней. Прогресс пропорционален сумме принятых ставок и не зависит от выигрыша или проигрыша.": "Characters unlock through total progress. Each character's second look unlocks by playing with her. Progress is proportional to accepted stakes, regardless of wins or losses.",
  "Тестовые монеты клуба · вход без ставки": "Club test coins · enter without a stake",
  "КАМЕРЫ ГОТОВЫ": "CAMERAS READY",
  "БЕСПЛАТНЫХ ВРАЩЕНИЙ": "FREE SPINS",
  "До трёх WILD остаются на местах, заряд ячеек сохраняется. Три камеры добавляют два вращения, максимум 20 всего. Линия из закреплённых WILD оплачивается один раз за спин.": "Up to three WILDs stay in place and cell charges persist. Three cameras add two spins, up to 20 total. An all-locked-WILD line pays once per spin.",
  "НАЧАТЬ ФОТОСЕССИЮ": "START PHOTO SHOOT",
  "Продолжение бесплатно. Ставка уже принята.": "Continue for free. The stake was already accepted.",
  "СЪЁМКА ЗАВЕРШЕНА": "SHOOT FINISHED",
  "ИТОГ ФОТОСЕССИИ": "PHOTO SHOOT TOTAL",
  "Выплата зачислена один раз. Прогресс сохранён в альбоме.": "The payout was credited once. Progress is saved in the album.",
  "ТВОЯ КОЛЛЕКЦИЯ": "YOUR COLLECTION",
  "АЛЬБОМ ГЕРОИНЬ": "CHARACTER ALBUM",
  "Прогресс зависит от суммы принятых ставок. Для второго образа играй с выбранной героиней. Выигрыш и проигрыш не влияют на открытие.": "Progress depends on accepted stakes. Play with the selected character to unlock her second look. Wins and losses do not affect unlocks.",
  "Прогресс альбома": "Album progress",
  "ВЕРНУТЬСЯ В ИГРУ": "BACK TO GAME",
  "Все героини открыты": "All characters unlocked",
