  "ВЫИГРЫШ ПРИНЯТ": "WIN ACCEPTED",
  "ФЕСТИВАЛЬ ПРОДОЛЖАЕТСЯ": "FESTIVAL CONTINUES",
  "НОВЫЕ СЛАДОСТИ В СЛЕДУЮЩЕМ ВРАЩЕНИИ": "NEW SWEETS IN THE NEXT SPIN",
  "КАЖДЫЙ КАСКАД ГОТОВИТ СЮРПРИЗ": "EVERY CASCADE BRINGS A SURPRISE",
  "Выигрышные конфеты исчезают. Новые падают сверху. До 20 каскадов.": "Winning candies disappear. New ones fall from above. Up to 20 cascades.",
  "Волчки на выигрышном каскаде повышают множитель до выплаты.": "Spinners on a winning cascade increase the multiplier before payout.",
  "ЧЕТЫРЕ БИЛЕТА": "FOUR TICKETS",
  "10 бесплатных вращений. В фестивале энергия сохраняется.": "10 free spins. Energy persists during the festival.",
  "СЛАДКИЙ ФЕСТИВАЛЬ": "SWEET FESTIVAL",
  "10 БЕСПЛАТНЫХ ВРАЩЕНИЙ": "10 FREE SPINS",
  "ВРАЩЕНИЙ": "SPINS",
  "Энергия начинается с ×1 и сохраняется между вращениями до ×50. Три билета на конечном поле добавляют ещё три вращения, всего до 30.": "Energy starts at ×1 and persists between spins up to ×50. Three tickets on the final board add three spins, capped at 30 total.",
  "Ставка:": "Stake:",
  "· стоимость 35×": "· costs 35×",
  "Одна покупка с тестового кошелька. Выплата может быть ниже стоимости или равна нулю.": "One purchase from the test wallet. Payout may be lower than the cost or zero.",
  "НАЧАТЬ ЗА": "START FOR",
  "Вернуться в игру": "Back to game",
  "ФЕСТИВАЛЬ ОТКРЫТ": "FESTIVAL UNLOCKED",
  "Множитель сохраняется между вращениями. Три билета добавляют ещё три вращения, до 30 в сумме.": "The multiplier persists between spins. Three tickets add three more spins, capped at 30 total.",
  "НАЧАТЬ ФЕСТИВАЛЬ": "START FESTIVAL",
  "Ставка принята. Продолжение бесплатно.": "Stake accepted. Continue for free.",
  "ПРАЗДНИК ЗАВЕРШЁН": "CELEBRATION FINISHED",
  "ИТОГ ФЕСТИВАЛЯ": "FESTIVAL TOTAL",
  "Выплата уже зачислена в кошелёк один раз.": "Payout already credited to the wallet once.",
  "ЖУРНАЛ ЯРМАРКИ": "FAIR LOG",
  "Фестиваль сохранён. Выплата поступит после завершения.": "Festival saved. Payout arrives after completion.",
  "Здесь появится подтверждённая история твоего раунда.": "Your round's confirmed history will appear here.",
  "{0} каскадов · ×{1} · {2} билетов{3}": "{0} cascades · ×{1} · {2} tickets{3}",
  "ПРАВИЛА ЯРМАРКИ": "FAIR RULES",
  "КАК ИГРАЕТ CARAMEL": "HOW CARAMEL PLAYS",
  "Совпадения в любом месте": "Matches anywhere",
  "Поле 6×5. Восемь и более одинаковых конфет выигрывают независимо от расположения. Они исчезают, остальные падают вниз, свободные ячейки заполняются. До 20 выигрышных каскадов за вращение. Билет и волчок сами не оплачиваются.": "6×5 board. Eight or more matching candies win regardless of location. They disappear, the rest fall down and empty cells refill. Up to 20 winning cascades per spin. Tickets and spinners do not pay on their own.",
  "Энергия до ×50": "Energy up to ×50",
  "Волчки +2, +3, +5 и +10 на выигрышном поле добавляют энергию до выплаты этого каскада, затем исчезают вместе с выигрышными конфетами. Например, ×1 и +2 дают ×3. Без выигрышной группы волчки не срабатывают. Обычное вращение начинает с ×1, фестиваль сохраняет множитель между бесплатными вращениями.": "Spinners +2, +3, +5 and +10 on a winning board add energy before that cascade's payout, then disappear with winning candies. For example, ×1 plus +2 gives ×3. Spinners do not activate without a winning group. Regular spins start at ×1; the festival preserves the multiplier between free spins.",
  "Билеты и фестиваль": "Tickets and festival",
  "Считаются билеты на конечном поле, после каскадов. Четыре и более дают 10 бесплатных вращений. Фестиваль начинается с ×1. Внутри три и более билета добавляют три вращения, максимум 30 за весь фестиваль. Билеты не накапливаются между отдельными обычными ставками.": "Tickets count on the final board after cascades. Four or more give 10 free spins. The festival starts at ×1. Inside it, three or more tickets add three spins, capped at 30 for the whole festival. Tickets do not accumulate across separate regular bets.",
  "Выплаты от общей ставки, до множителя": "Payouts from total stake, before multiplier",
  "Покупка фестиваля стоит 35 ставок, списывается один раз. Максимальная выплата всего раунда вместе с бесплатными вращениями: 5 000 базовых ставок. При достижении предела оставшиеся каскады и вращения заканчиваются. Выплаты округляются вниз до 0,01 монеты.": "Buying the festival costs 35 stakes, debited once. Maximum total round payout including free spins: 5,000 base stakes. Reaching the cap ends remaining cascades and spins. Payouts round down to 0.01 coin.",
  "Одна ставка и одна итоговая выплата. При обрыве связи подтверждается прежний UUID, новая ставка не нужна. Закрытие, скрытие окна и ошибка останавливают авто. Фестиваль можно продолжить из сохранённого состояния. Авто выполняет выбранные 10, 25 или 50 платных вращений и останавливается при входе в фестиваль.": "One stake and one final payout. A lost connection confirms the previous UUID without a new stake. Closing or hiding the window and errors stop auto play. The festival resumes from saved state. Auto runs the selected 10, 25 or 50 paid spins and stops on festival entry.",
  "Собственная версия Royal: свои иллюстрации, звуки и вероятности событий. Демонстрационная игра на тестовые монеты.": "Original Royal version: our own illustrations, sounds and event probabilities. A demo game with test coins.",
