  "Посмотреть все": "View all",
  "Правила, символы и выплаты": "Rules, symbols and payouts",
  "На каждой из": "On each of the",
  "линий оплачивается одна лучшая цепочка от трёх обычных знаков слева. WILD заменяет обычные знаки. Затем первые два сборщика по порядку чтения поля получают каждый все оставшиеся сокровища. Третий и следующие сборщики не дают отдельной награды.": "paylines, one best chain of three or more regular symbols from the left pays. WILD substitutes for regular symbols. Then the first two collectors in reading order each collect all remaining treasures. The third and subsequent collectors give no separate reward.",
  "Метка «ВЕС» у сокровища показывает вес символа, а не сумму в кошельке. Вес определяется его позицией и равен 2, 3, 4 или 5. Сбор не удаляет знаки с поля. Выплата каждой награды уже учитывает все её символы и прибавляется к общей сумме один раз.": "A treasure's WEIGHT label shows symbol weight, not a wallet amount. Weight is determined by position and is 2, 3, 4 or 5. Collection does not remove symbols. Each displayed reward already includes all of its symbols and is added to the total once.",
  "Ставка указана за все линии и весь раунд. Коэффициент каждой награды округляется вниз до четырёх знаков, затем выплата до 0,01 монеты. На счёт поступает общая выплата за завершённый раунд. История, просмотр линий и проверка прежнего хода не требуют новой ставки.": "The stake covers all paylines and the entire round. Each reward's factor rounds down to four decimal places, then its payout to 0.01 coin. The total payout is credited after the round ends. History, payline viewing and checking a previous move require no new stake.",
  "Жемчужный свет и сокровища моря": "Pearl light and sea treasures",
  "Тёплое солнце, плоды и золотые семена": "Warm sunshine, fruit and golden seeds",
  "три": "three",
  "четыре": "four",
  "Хранители находят сундуки сокровищ": "Guardians find treasure chests",
  "Солнце расширяется на трёх внутренних барабанах": "The sun expands on the three inner reels",
  "Три хранителя на основном поле открывают ровно два новых бесплатных вращения. Новая ставка не нужна. Символы не закрепляются, бонус не продлевается.": "Three guardians on the base board unlock exactly two new free spins. No new stake is needed. Symbols do not lock and the bonus does not extend.",
  "Солнце WILD расширяется на весь барабан только в трёх внутренних колонках. Два крайних барабана остаются прежними. Преобразование происходит до сбора. В этой игре один платный этап, без бесплатного бонуса.": "The WILD sun expands across a whole reel only in the three inner columns. The two outer reels stay unchanged. Transformation happens before collection. This game has one paid stage and no free bonus.",
