  "Поймай сигнал. Открой порталы. Запусти миссию.": "Catch the signal. Open portals. Launch a mission.",
  "Три и более совпадения слева. WILD заменяет обычные символы.": "Three or more matches from the left. WILD substitutes for regular symbols.",
  "3 ПОРТАЛА": "3 PORTALS",
