  "Будет списано один раз с тестового кошелька. Возможна нулевая выплата.": "Debited from the test wallet once. Payout may be zero.",
  "Недостаточно тестовых монет. Выбери меньшую ставку.": "Not enough test coins. Choose a smaller stake.",
