  "Множитель с ×3. Эхо встречается вдвое чаще.": "Multiplier starts at ×3. Echo occurs twice as often.",
  "ПОРТАЛ ОТКРЫТ": "PORTAL OPEN",
  "Бесплатных вращений": "Free spins",
  "Энергия начинается с ×": "Energy starts at ×",
  "и может увеличиться перед вращением до ×50.": "and may increase before a spin, up to ×50.",
  "ВПЕРЁД В МИССИЮ": "ON TO THE MISSION",
  "Ставка уже принята. Продолжение бесплатно.": "Stake already accepted. Continue for free.",
  "ВОЗВРАЩЕНИЕ ДОМОЙ": "RETURNING HOME",
  "Выигрыш уже зачислен в кошелёк.": "Winnings already credited to the wallet.",
  "БОРТОВОЙ ЖУРНАЛ": "SHIP'S LOG",
  "ИСТОРИЯ МИССИИ": "MISSION HISTORY",
  "Серия сохранена. Выплата поступит после завершения.": "Series saved. Payout arrives after completion.",
  "Здесь появится история твоего раунда.": "Your round history will appear here.",
  "Основное вращение": "Base spin",
  "Бесплатное вращение": "Free spin",
  "Стоимость {0}": "Cost {0}",
  "Стоимость 0,00": "Cost 0.00",
  "ЭХО ·": "ECHO ·",
  "КАРТА КОСМИЧЕСКОГО ПОБЕГА": "COSMIC ESCAPE MAP",
  "ПРАВИЛА И ВЫПЛАТЫ": "RULES AND PAYOUTS",
  "Пять барабанов, три ряда, 20 фиксированных линий. Все линии всегда активны. На каждой оплачивается только наибольшая выплата за совпадение из трёх и более символов слева. Значения таблицы умножаются на общую ставку.": "Five reels, three rows, 20 fixed paylines. All paylines are always active. Each pays only the highest payout for three or more matching symbols from the left. Table values multiply the total stake.",
  "WILD заменяет обычные символы. Портал не участвует в линиях: 3, 4 и 5 порталов в основной игре открывают 10, 12 и 15 бесплатных вращений.": "WILD substitutes for regular symbols. Portals do not count in paylines: 3, 4 and 5 portals in the base game unlock 10, 12 and 15 free spins.",
  "В миссии энергия усиливает все выигрышные линии. Перед бесплатным вращением она может увеличиться и сохраняется между вращениями до ×50. Луч материнского корабля создаёт целый WILD-барабан. Второй отголосок даёт второе поле с текущим множителем без новой ставки.": "During a mission, energy boosts all winning lines. It may increase before a free spin and persists between spins up to ×50. The mothership beam creates a full WILD reel. A second echo gives another board at the current multiplier without a new stake.",
  "20 фиксированных линий": "20 fixed paylines",
  "Миссии: Звёздный хаос (40 ставок, 10 вращений, ×1), Вторжение (75 ставок, 12 вращений, ×1, до двух лучей), Дальнее эхо (135 ставок, 15 вращений, ×3, эхо встречается чаще).": "Missions: Star Chaos (40 stakes, 10 spins, ×1), Invasion (75 stakes, 12 spins, ×1, up to two beams), Distant Echo (135 stakes, 15 spins, ×3, more frequent echo).",
  "Максимум за раунд:": "Maximum per round:",
  "базовых ставок. Выплаты округляются вниз до 0,01 монеты. Ставка списывается один раз, весь выигрыш серии зачисляется один раз по окончании.": "base stakes. Payouts round down to 0.01 coin. The stake is debited once and the entire series payout is credited once at completion.",
  "Авто выполняет конечное число платных вращений: 10, 25 или 50. При входе в естественную миссию платное авто останавливается. Скрытие окна, выход, смена аккаунта или ошибка останавливают авто. Миссия сохраняется на сервере и продолжается без повторной ставки.": "Auto runs a finite number of paid spins: 10, 25 or 50. Entering a natural mission stops paid auto play. Hiding the window, exiting, changing accounts or errors stop auto play. The mission is saved on the server and continues without a repeat stake.",
  "Расчётный возврат новых ставок: около 96% на длинной дистанции. Отдельный раунд может завершиться без выплаты.": "Theoretical return for new bets: about 96% over the long run. An individual round may have no payout.",
  "Собственная версия Royal: свои изображения, звуки и частоты событий. Вероятности исходной игры не опубликованы.": "Original Royal version: our own images, sounds and event frequencies. Source game probabilities are not public.",
  "Заменяет обычные символы": "Substitutes for regular symbols",
  "Множитель растёт во время полёта. Забери выплату до остановки. Результат и выплату подтверждает сервер.": "The multiplier rises during flight. Cash out before it stops. The server confirms the result and payout.",
  "Движение следует только последнему подтверждённому времени сервера. При задержке связи множитель остаётся на подтверждённом значении. Незавершённая партия сохраняется при закрытии.": "Motion follows only the latest confirmed server time. During connection delays the multiplier stays at its confirmed value. Closing saves an unfinished game.",
  "Общий тестовый кошелёк клуба. Множители включают ставку, начисление округляется вниз до 0,01 монеты.": "Shared club test wallet. Multipliers include the stake; credits round down to 0.01 coin.",
  "{0} демомонет": "{0} demo coins",
