  "Нижняя граница входит в цель": "Lower boundary included in target",
  "Числа от 00,00 до 99,99 равновероятны. «Ниже» означает строго меньше порога; «от порога и выше» включает равенство.": "Numbers from 00.00 to 99.99 are equally likely. Under means strictly below the threshold; At least includes equality.",
  "Число от 00,00 до 99,99 должно попасть в выбранный коридор. Нижняя граница включена, верхняя исключена.": "A number from 00.00 to 99.99 must fall in the selected corridor. The lower boundary is included, the upper excluded.",
  "Равновероятные целые числа от 0 до 99. «Ниже» означает число меньше выбранного шанса; «выше» начинается с 100 минус шанс.": "Equally likely integers from 0 to 99. Under means below the selected chance; Over begins at 100 minus the chance.",
  "Множитель округлён до четырёх знаков; фактический возврат зависит от порога и ставки.": "The multiplier is rounded to four decimal places; actual return depends on the threshold and stake.",
  "Расчётный возврат близок к 98%; округление конкретной выплаты может немного уменьшать его.": "Theoretical return is close to 98%; rounding a specific payout may reduce it slightly.",
  "Не удалось подтвердить число и выплату. Обнови кошелёк.": "Could not confirm the number and payout. Refresh your wallet.",
