  "Линия {0}, барабан {1}: {2}": "Payline {0}, reel {1}: {2}",
  "Декоративный символ, не участвует в выплате": "Decorative symbol, no payout",
  "ROYAL CLUB / ФРУКТОВЫЕ ИСТОРИИ": "ROYAL CLUB / FRUIT STORIES",
  "Проверить тот же ход": "Check the same move",
  "Три одинаковых на одной оплаченной линии приносят награду. Пары и смешанные символы не выигрывают. Выплата включает ставку. RTP 97% на длинной дистанции.": "Three matching symbols on a paid payline win a reward. Pairs and mixed symbols do not win. Payout includes the stake. Long-run RTP 97%.",
  "Новых бонусов или бесплатных вращений нет. Ставка и выплата видны в общем кошельке.": "No new bonuses or free spins. Stakes and payouts appear in the shared wallet.",
  "EZSlotsJS, Apache2.0 и NOTICE": "EZSlotsJS, Apache2.0 and NOTICE",
  "Драгоценный сад. Одна королевская линия.": "A precious garden. One royal payline.",
  "Светлый пассаж. Две или три независимые линии.": "A bright passage. Two or three independent paylines.",
  "Верхний и нижний ряды декоративны, в выплате участвует только центральный ряд.": "Top and bottom rows are decorative; only the centre row pays.",
  "Общая ставка делится на две или три независимые строки в сотых монеты. Остаток получают первые строки. Выключенная третья строка не участвует.": "The total stake is split between two or three independent rows in hundredths of a coin. The first rows receive any remainder. The disabled third row does not participate.",
  "Результат не удалось показать. Обнови кошелёк.": "Could not show the result. Refresh your wallet.",
  "Барабаны вращаются. Встречай свою комбинацию.": "Reels spinning. Meet your winning combination.",
  "Ответ ещё не подтверждён. Проверь ту же операцию без новой ставки.": "Response not confirmed yet. Check the same operation without another stake.",
