  "Печать двора": "Mint seal",
  "Лунный медальон": "Moon medallion",
  ", закреплена, {0} монет": ", locked, {0} coins",
  "Три монеты открывают бонус": "Three coins unlock the bonus",
  "Ровно два бесплатных этапа, без продления": "Exactly two free stages, no extension",
  "барабана,": "reels,",
  "Монеты остаются на месте во время бонуса": "Coins stay in place during the bonus",
  "Оплаченные монеты и сборщики": "Paid coins and collectors",
  "Три или больше монет на основном поле открывают ровно два бесплатных этапа. Оплаченные монеты закрепляются на своих местах. Каждый новый этап оплачивает только новые монеты. Пустой этап не продлевает бонус. Одной или двух монет недостаточно для бонуса, отдельная монетная выплата за них не начисляется.": "Three or more coins on the base board unlock exactly two free stages. Paid coins lock in place. Each new stage pays only for new coins. An empty stage does not extend the bonus. One or two coins do not unlock it and receive no separate coin payout.",
  "На основном поле активны": "The base board has",
  "линий: от трёх обычных знаков слева, WILD их заменяет.": "paylines: three or more regular symbols from the left; WILD substitutes for them.",
  "В бесплатных этапах линии и сборщики не оплачиваются.": "Paylines and collectors do not pay during free stages.",
  "Метка «ВЕС» у неоплаченной монеты означает вес символа, а не сумму в кошельке. Число на закреплённой монете показывает её уже учтённую награду в монетах клуба. Старые монеты не оплачиваются повторно. Полное поле не даёт дополнительного джекпота.": "WEIGHT on an unpaid coin means symbol weight, not a wallet amount. A locked coin's number shows its reward already counted in club coins. Old coins do not pay again. A full board gives no extra jackpot.",
  "Тёплый свет металла и золотые замки": "Warm metal light and golden locks",
  "Сокровища под фонарями ночного базара": "Treasures beneath night market lanterns",
  "Серебряные медальоны в лунном свете": "Silver medallions in moonlight",
  "Первые два торговца-сборщика по порядку чтения поля получают каждый все монеты основного поля. Это отдельная награда; она возможна и без монетного бонуса.": "The first two merchant collectors in board reading order each receive all base-board coins. This is a separate reward, possible without the coin bonus.",
  "Шестерня или печать не открывает бонус и не даёт отдельной награды.": "The gear or seal does not unlock a bonus or give a separate reward.",
