  ", закреплён": ", locked",
  "Ночная станция. WILD остаются на своих местах.": "Night station. WILDs stay in place.",
  "Тихий водоём. Сохраняй свои знаки.": "A quiet pond. Keep your symbols.",
  "Ночной город. Проводник идёт налево.": "Night city. The conductor moves left.",
  "WILD закрепляется только в собственной ячейке и сохраняется на бесплатных вращениях. Новые WILD тоже закрепляются. На оплаченной цепочке WILD усиливают именно эту линию: 2×, 3× или 4×.": "WILD locks only in its own cell and stays during free spins. New WILDs lock too. Within a paid chain, WILDs boost that specific line by 2×, 3× or 4×.",
  "Обычный знак в верхней левой ячейке задаёт цель этапа после сохранения прежних закреплений. Совпадающие обычные знаки закрепляются каждый в своей ячейке, сохраняя свой вид. Если верхний левый знак особый, новых закреплений цели пока нет. Игрок не выбирает цель кнопкой.": "The regular top-left symbol sets the stage target after existing locks are preserved. Matching regular symbols lock in their own cells, retaining their identity. If the top-left symbol is special, no new target locks occur yet. The player does not select a target with a button.",
  "В основном вращении дополнительной WILD-колонны нет. На первом бесплатном вращении проводник занимает пятую колонну, на втором четвёртую. Предыдущая колонна не закрепляется: каждый раз открывается новое поле.": "No extra WILD column in the base spin. In the first free spin, the conductor occupies the fifth column, then the fourth in the second. The previous column does not stay locked: a fresh board is revealed each time.",
  ", три ряда": ", three rows",
  "Три SCATTER на итоговом поле открывают ровно два бесплатных новых вращения без новой ставки. Бонус не продлевается. Накопленное начисляется после завершения всего раунда.": "Three SCATTERs on the final board unlock exactly two new free spins without a new stake. No retriggers. Accumulated winnings are credited after the entire round.",
  "Базовые награды за одну линию": "Base rewards per payline",
  ". Выбирается одна лучшая цепочка слева от трёх символов. WILD заменяет обычный знак; отдельной оплаты WILD или декоративного знака нет.": ". One best chain of three or more symbols from the left is selected. WILD substitutes for a regular symbol; WILD and decorative symbols have no separate payout.",
