  "Возврат части ставки · общий итог": "Partial stake return · overall total",
  "Заверши сохранённый раунд по прежним правилам. Затем откроется новая версия с полными правилами.": "Finish the saved round under its previous rules. The new version with full rules will then open.",
  "Прежний раунд завершён. Можно открыть новую версию с полными правилами.": "Previous round finished. Open the new version with full rules.",
