  "СЛЕДУЮЩИЙ ЗАЕЗД ЖДЁТ НА СТАРТЕ": "THE NEXT RACE AWAITS AT THE START",
  "ПОЛНОЧЬ. МОКРЫЙ АСФАЛЬТ. ПОЛНЫЙ БАК.": "MIDNIGHT. WET ASPHALT. FULL TANK.",
  "20 ЛИНИЙ И КАСКАДЫ": "20 PAYLINES AND CASCADES",
  "Три символа слева дают выигрыш. WILD помогает. Выигрышные символы падают каскадом.": "Three symbols from the left win. WILD helps. Winning symbols cascade.",
  "РАЗГОН И НИТРО": "ACCELERATION AND NITRO",
  "Каждый выигрыш повышает следующую передачу. Два баллона на выигрышных полях дают один бесплатный рывок.": "Each win raises the next gear. Two bottles on winning boards give one free boost.",
  "3 / 4 / 5+ флагов в конце дают 8 / 10 / 12 вращений. Каждое начинает со второй передачи.": "3 / 4 / 5+ flags at the end award 8 / 10 / 12 spins. Each starts in second gear.",
  "ФИНИШНЫЕ ФЛАГИ СОБРАНЫ": "FINISH FLAGS COLLECTED",
  "Каждое вращение начинает со второй передачи ×2. Три флага на конечном поле добавляют ещё два вращения, максимум 20 за весь раунд. Нитро заряжается заново в каждом вращении.": "Each spin starts in second gear, ×2. Three flags on the final board add two spins, capped at 20 for the whole round. Nitro recharges on every spin.",
  "НАЧАТЬ ГОНКУ": "START RACE",
  "ФИНИШНАЯ ЧЕРТА": "FINISH LINE",
  "ИТОГ БОНУСНОЙ ГОНКИ": "BONUS RACE TOTAL",
  "ИСТОРИЯ ЗАЕЗДА": "RACE HISTORY",
  "Гонка сохранена. Выплата поступит после финиша.": "Race saved. Payout arrives after the finish.",
  "Здесь появится подтверждённая история раунда.": "Confirmed round history will appear here.",
  "{0} каскадов · передача ×{1} · {2}{3} флагов{4}": "{0} cascades · gear ×{1} · {2}{3} flags{4}",
  "нитро-рывок ·": "nitro boost ·",
  "БРИФИНГ ПЕРЕД СТАРТОМ": "PRE-RACE BRIEFING",
  "КАК ИГРАЕТ НИТРО-ЗАЕЗД": "HOW NITRO RUN PLAYS",
  "20 линий, одна общая ставка": "20 paylines, one total stake",
  "Разгон со следующего каскада": "Acceleration from the next cascade",
  "Обычное вращение начинает с ×1, бесплатное с ×2. Выигрыш оплачивается на текущей передаче, затем следующая повышается на один до ×5. Между вращениями передача не сохраняется.": "Regular spins start at ×1, free spins at ×2. A win pays at the current gear; the next gear then rises by one, up to ×5. Gear does not persist between spins.",
  "Нитро-рывок": "Nitro boost",
  "Баллоны собираются только при выигрыше на поле и исчезают вместе с выигрышными символами. Нужно два за одно вращение. При первом поле без выигрыша нитро сжигается и целиком перезапускает поле на текущей передаче. Только один рывок за вращение. Флаги учитываются только на конечном поле. На 12-м показе или при лимите выплаты поле больше не перезапускается.": "Bottles collect only on winning boards and disappear with winning symbols. Two are needed within one spin. On the first non-winning board, nitro burns and completely restarts the board at the current gear. One boost per spin. Flags count only on the final board. No restart on the 12th reveal or at the payout cap.",
  "Таблица выплат от общей ставки, до передачи": "Paytable from total stake, before gear",
  "WILD заменяет обычные символы, на линии платится только лучшая комбинация. Пересекающиеся линии оплачиваются отдельно. Баллон и флаг сами не оплачиваются. Максимум всего раунда: 3 000 ставок. При достижении лимита остаток бонуса завершается. При ограничении последняя линия может оплачиваться частично.": "WILD substitutes for regular symbols; each line pays only its best combination. Crossing lines pay separately. Bottles and flags do not pay themselves. Total round cap: 3,000 stakes. Reaching it ends the remaining bonus. The final capped line may pay partially.",
  "Все 20 линий": "All 20 paylines",
  "Одна ставка и одна итоговая выплата на раунд. При обрыве связи подтверждается прежний ход. Закрытие или скрытие окна останавливает авто. Бонусная гонка сохраняется. Авто делает выбранные 10, 25 или 50 платных вращений и останавливается при входе в бонус. Покупки бонуса нет.": "One stake and one final payout per round. Disconnection confirms the previous move. Closing or hiding the window stops auto play. The bonus race is saved. Auto runs the selected 10, 25 or 50 paid spins and stops on bonus entry. No bonus purchase.",
  "Оценка долгосрочного возврата: около 96,2% от суммы ставок, включая бонусы. Это среднее на длинной серии, а не обещание результата отдельного заезда.": "Estimated long-run return: about 96.2% of stakes, including bonuses. An average over many rounds, not a promise for an individual race.",
  "Собственная игра Royal: оригинальное оформление, звуки и серверная математика. Только тестовые монеты клуба.": "Original Royal game: original visuals, sounds and server maths. Club test coins only.",
