  "{0} · {1} звёзд{2}": "{0} · {1} stars{2}",
  "Вращение": "Spin",
  "Выплата": "Payout",
  "ПРАВИЛА ТЕАТРА": "THEATRE RULES",
  "Пять барабанов, четыре ряда, 14 фиксированных линий. Все линии всегда активны. От трёх совпадений слева оплачивается лучший результат на каждой линии. Выплаты разных линий складываются. Таблица умножается на базовую ставку.": "Five reels, four rows, 14 fixed paylines. All lines are always active. Each pays its best result for three or more matches from the left. Different line payouts add together. The table multiplies the base stake.",
  "WILD заменяет платные символы. Три самоцвета в основной игре дают Spotlight: 10 бесплатных вращений. Четыре или пять дают Super Encore: 10 вращений со звездой на сцене и тремя собранными самоцветами.": "WILD substitutes for paying symbols. Three gems in the base game give Spotlight: 10 free spins. Four or five give Super Encore: 10 spins with a star on stage and three collected gems.",
  "Каждые три самоцвета в бонусе добавляют постоянную звезду на свободный барабан и два вращения. Новые звёзды применяются со следующего спина. У каждой свой барабан. Множители 2, 3, 4, 5, 8, 10, 20, 50 или 100 складываются только у звёзд, участвующих в выигрышной комбинации: 3 + 5 = 8. После появления всех пяти звёзд новые самоцветы и вращения не добавляются. Максимум 20 бесплатных вращений.": "Every three gems in the bonus add a permanent star on a free reel and two spins. New stars apply from the next spin. Each has its own reel. Multipliers 2, 3, 4, 5, 8, 10, 20, 50 or 100 add only for stars participating in a winning combination: 3 + 5 = 8. After all five stars appear, no more gems or spins are added. Maximum 20 free spins.",
  "Booster стоит 2 базовые ставки за вращение, шанс бонуса ×3. Hyper стоит 10 ставок, шанс ×20. Режимы используют разные частоты обычных символов. Их активация бесплатна. Spotlight стоит 100 ставок, Super Encore стоит 300. Платное входное поле бонуса не даёт отдельной линейной выплаты.": "Booster costs 2 base stakes per spin, bonus chance ×3. Hyper costs 10 stakes, chance ×20. Modes use different regular-symbol frequencies. Activation is free. Spotlight costs 100 stakes, Super Encore 300. The paid bonus entry board gives no separate line payout.",
  "14 фиксированных линий": "14 fixed paylines",
  "Предел за весь раунд: 10 000 базовых ставок. При достижении предела серия заканчивается. Ставка списывается один раз, общая выплата начисляется один раз после завершения. Прерванная серия сохраняется на сервере и продолжается бесплатно.": "Whole-round cap: 10,000 base stakes. Reaching it ends the series. The stake is debited once; the total payout is credited once after completion. An interrupted series is saved on the server and continues for free.",
  "Авто выполняет 10, 25 или 50 платных вращений. Естественный бонус останавливает платное авто. Выход, скрытие вкладки, ошибка или смена аккаунта останавливают авто и звук. Скорость и уменьшение движения меняют только показ.": "Auto runs 10, 25 or 50 paid spins. A natural bonus stops paid auto play. Exiting, hiding the tab, an error or changing accounts stop auto play and sound. Speed and reduced motion affect presentation only.",
  "Собственная версия Royal: новые изображения, музыка и звуковые эффекты, собственные вероятности событий. Частоты исходного демо не опубликованы. Оценка возврата на длинной дистанции: около 96% во всех пяти режимах. Отдельная серия может закончиться без выплаты.": "Original Royal version: new images, music and sound effects, original event probabilities. Source demo frequencies are not public. Estimated long-run return: about 96% in all five modes. An individual series may have no payout.",
  "Праздничный фонарь": "Festival lantern",
