  "СИГНАЛ": "SIGNAL",
  "Ночной праздник. Встречай свои комбинации.": "Night celebration. Meet your winning combinations.",
  "Медная трасса. Связанные барабаны.": "Copper track. Linked reels.",
  "Зимняя почта. Раскрой тайные посылки.": "Winter post. Reveal mystery parcels.",
  "Шесть барабанов, четыре ряда. Три небесных врата на основном поле открывают ровно два бесплатных новых поля, без новой ставки и продления бонуса.": "Six reels, four rows. Three sky gates on the base board unlock exactly two free fresh boards, with no new stake or retriggers.",
  "От двух до пяти первых барабанов связаны с первым и показывают одинаковые знаки. Остальные независимы. В этой игре один платный этап, без бесплатного бонуса, даже при нескольких сигнальных лампах.": "The first two to five reels link to the first and show identical symbols. The rest are independent. One paid stage, no free bonus, even with several signal lamps.",
  "Тайные коробки раскрываются в один обычный знак по исходному верхнему левому символу этого этапа. Раскрываются только тайные коробки. Три знака доставки на основном поле открывают ровно два бесплатных новых поля. Доставка не собирает монеты.": "Mystery boxes reveal one regular symbol based on this stage's original top-left symbol. Only mystery boxes transform. Three delivery symbols on the base board unlock exactly two free fresh boards. Delivery does not collect coins.",
  "ВОЗМОЖНЫХ ПУТЕЙ": "POSSIBLE WAYS",
  "Способы выигрыша от трёх соседних барабанов слева": "Winning ways from three adjacent reels on the left",
  "Все способы активны": "All ways active",
  "От трёх барабанов": "From three reels",
  "Подтверждённые награды за способы": "Confirmed ways rewards",
  "Правила, символы и способы выигрыша": "Rules, symbols and ways to win",
  "От трёх соседних барабанов слева оплачиваются способы для каждого обычного знака. WILD заменяет обычные знаки. Число путей равно произведению количества подходящих ячеек на этих барабанах. Полностью WILD-пути исключаются из обычной награды и оплачиваются отдельно, со своей длиной. Это не фиксированные линии и не обещание": "Ways pay for each regular symbol from three adjacent reels on the left. WILD substitutes for regular symbols. The number of ways is the product of matching cell counts on those reels. All-WILD paths are excluded from regular rewards and paid separately at their own length. These are not fixed paylines or a promise of",
  "выигрышей.": "wins.",
  "Базовые награды за один оплачиваемый путь:": "Base rewards per paid way:",
  "Ставка указана за все способы и весь раунд. Множитель включает ставку. Коэффициент каждой награды округляется вниз до четырёх знаков, затем её выплата до 0,01 монеты; выплаты суммируются. На счёт поступает общая выплата за раунд. Историю можно посмотреть без новой ставки.": "The stake covers all ways and the entire round. Multipliers include the stake. Each reward factor rounds down to four decimal places, then its payout to 0.01 coin; payouts are added. The total round payout is credited. History requires no new stake.",
  "НЕБЕСНЫЕ КОМБИНАЦИИ": "SKY COMBINATIONS",
