  "Вероятности и правила": "Probabilities and rules",
  "Выбери одну из четырёх целей. Все физические сектора равновероятны. Повторяющиеся знаки занимают отдельные сектора. Множитель включает ставку.": "Choose one of four targets. All physical segments are equally likely. Repeated symbols occupy separate segments. Multipliers include the stake.",
  "Расчётный возврат 98%. Один оплаченный результат, без бесплатных вращений. При несовпадении цели выплата равна нулю.": "Theoretical return 98%. One paid result, no free spins. A target miss pays zero.",
