  "Бонусное перо": "Bonus feather",
  "Искра солнца": "Sun spark",
  "10 ЛИНИЙ": "10 PAYLINES",
  "Три бонусных знака открывают два этапа": "Three bonus symbols unlock two stages",
  "Бесплатные вращения не продлеваются": "Free spins do not retrigger",
  "10 линий": "10 paylines",
  "Награды показанного этапа": "Displayed stage rewards",
  "Посмотреть все 10 линий": "View all 10 paylines",
  "На основном поле три или больше бонусных знака открывают ровно два бесплатных вращения. Новая ставка не нужна. Бонус не продлевается, символы не закрепляются.": "Three or more bonus symbols on the base board unlock exactly two free spins. No new stake needed. No retriggers or locked symbols.",
  "Активны все 10 линий. От трёх обычных знаков подряд слева дают одну лучшую награду линии. WILD заменяет обычные знаки.": "All 10 paylines are active. Three or more consecutive regular symbols from the left pay one best reward per line. WILD substitutes for regular symbols.",
  "Ставка указана за все линии и весь раунд. Коэффициент каждой награды округляется вниз до четырёх знаков, затем выплата до 0,01 монеты. На счёт поступает общая выплата за завершённый раунд. История и проверка прежнего хода не требуют новой ставки.": "The stake covers all paylines and the entire round. Each reward factor rounds down to four decimal places, then payout to 0.01 coin. The total payout is credited after the round ends. History and checking a previous move require no new stake.",
  "Цветы, мягкий свет и два бонусных колеса": "Flowers, soft light and two bonus wheels",
  "Янтарные искры на тропе жар-птицы": "Amber sparks on the firebird trail",
  "Колесо появляется в каждом бесплатном этапе": "A wheel appears in every free stage",
  "Множитель уже учитывается в наградах линий": "The multiplier is already included in line rewards",
  "В каждом бесплатном этапе появляется одно отдельное цветочное колесо. Оно показывает сектор от 1 до 6 и свою награду, не меняя символ на поле. Два бесплатных этапа дают два колеса, без третьего этапа или дополнительного джекпота. Номер сектора не означает сумму в кошельке.": "Each free stage has one separate flower wheel. It shows a segment from 1 to 6 and its reward, without changing board symbols. Two free stages give two wheels, no third stage or extra jackpot. The segment number is not a wallet amount.",
  "Искры солнца усиливают награды линий текущего поля: множитель равен 1 плюс номер этапа (0,1 или2) плюс число искр. Достижимый максимум 7×. Множитель уже включён в каждую показанную награду линии. Искры не дают отдельную монетную выплату и не сохраняются на следующий этап. Ниже указаны базовые коэффициенты при 1×.": "Sun sparks boost current-board line rewards: multiplier equals 1 plus the stage index (0, 1 or 2) plus the number of sparks. Maximum 7×. The multiplier is already included in every displayed line reward. Sparks give no separate coin payout and do not persist to the next stage. Base coefficients at 1× are shown below.",
