  "Вирусный режим продолжается бесплатно.": "Viral mode continues for free.",
  "Вирусный режим на паузе. Нажми «Продолжить».": "Viral mode is paused. Press Continue.",
  "ПРОДОЛЖИТЬ РЕЖИМ": "CONTINUE MODE",
  "ЗАПУСТИТЬ МЕМЫ": "LAUNCH MEMES",
  "Игра сохранена. Продолжение без ставки.": "Game saved. Continue without another bet.",
  "3 папки = ещё 2 вращения": "3 folders = 2 more spins",
  "СЕТЬ ВОССТАНОВЛЕНА": "NETWORK RESTORED",
  "СЕТЬ {0} / 2": "NETWORK {0} / 2",
  "Одно переподключение за вращение": "One reconnect per spin",
  "Переподключение при остановке серии": "Reconnect when the cascade ends",
  "ВИРУСНЫЙ РЕЖИМ · {0} / {1}": "VIRAL MODE · {0} / {1}",
  "КАСКАД {0} · РАЗГОН ×{1}{2}": "CASCADE {0} · OVERCLOCK ×{1}{2}",
  "· СЕТЬ +{0}": "· NETWORK +{0}",
  "СОЕДИНЕНИЕ ПОТЕРЯНО · ПЕРЕПОДКЛЮЧЕНИЕ БЕЗ СТАВКИ": "CONNECTION LOST · RECONNECT WITHOUT A BET",
  "{0} ПАПКИ · ВИРУСНЫЙ РЕЖИМ ОТКРЫТ": "{0} FOLDERS · VIRAL MODE UNLOCKED",
  "12 ПОКАЗОВ ПОЛЯ · ЗАГРУЗКА ЗАВЕРШЕНА": "12 BOARDS · LOADING COMPLETE",
  "ВИРУСНЫЙ РЕЖИМ ПРОДОЛЖАЕТСЯ": "VIRAL MODE CONTINUES",
  "СИСТЕМА ГОТОВА К СЛЕДУЮЩЕМУ ВРАЩЕНИЮ": "SYSTEM READY FOR THE NEXT SPIN",
  "СИСТЕМА ГОТОВА. МЕМЫ ЗАГРУЖЕНЫ.": "SYSTEM READY. MEMES LOADED.",
  "CPU И ПЕРЕПОДКЛЮЧЕНИЕ": "CPU AND RECONNECT",
  "Каждый выигрыш разгоняет следующий каскад. Два значка сети на выигрышных полях дают одно бесплатное переподключение.": "Each win boosts the next cascade. Two network icons on winning boards grant one free reconnect.",
  "3 / 4 / 5+ папок в конце дают 8 / 10 / 12 вращений. Каждое начинает с ×2.": "3 / 4 / 5+ folders on the final board grant 8 / 10 / 12 spins. Each starts at ×2.",
  "ПАПКИ BONUS СОБРАНЫ": "BONUS FOLDERS COLLECTED",
  "Каждое вращение начинает с ×2. Три папки на конечном поле добавляют ещё два вращения, максимум 20 за весь раунд. Сеть заряжается заново в каждом вращении.": "Each spin starts at ×2. Three folders on the final board add two more spins, up to 20 in the round. The network charge resets each spin.",
  "ЗАПУСТИТЬ ВИРУС": "LAUNCH THE VIRUS",
  "СИСТЕМА ВОССТАНОВЛЕНА": "SYSTEM RESTORED",
  "ИТОГ ВИРУСНОГО РЕЖИМА": "VIRAL MODE TOTAL",
  "НЕДОСТАТОЧНО ПАМЯТИ": "OUT OF MEMORY",
  "ФАЙЛ СЛИШКОМ БОЛЬШОЙ": "FILE TOO LARGE",
  "Выплата уже в кошельке. Система работает нормально.": "The payout is already in your wallet. The system is running normally.",
  "ВОССТАНОВИТЬ СИСТЕМУ": "RESTORE SYSTEM",
  "ЖУРНАЛ МЕМОВ": "MEME HISTORY",
  "Игра сохранена. Выплата поступит после завершения раунда.": "Game saved. The payout will arrive when the round ends.",
  "{0} каскадов · разгон ×{1} · {2}{3} папок{4}": "{0} cascades · overclock ×{1} · {2}{3} folders{4}",
  "переподключение ·": "reconnect ·",
  "КАК ИГРАЕТ MEME OVERLOAD": "HOW TO PLAY MEME OVERLOAD",
  "Обычное вращение начинает с ×1, бесплатное с ×2. Выигрыш оплачивается на текущем множителе, затем он повышается на один до ×5. Между вращениями разгон сбрасывается.": "Paid spins start at ×1 and free spins at ×2. Wins use the current multiplier, which then increases by one up to ×5. Overclock resets between spins.",
  "Переподключение": "Reconnect",
  "Значки сети собираются только при выигрыше на поле и удаляются вместе с выигрышными мемами. Нужно два за одно вращение. При первом поле без выигрыша заряд расходуется и полностью обновляет поле с сохранением множителя. Только одно переподключение за вращение. Папки учитываются только на конечном поле. На 12-м показе или при лимите выплаты поле больше не обновляется.": "Network icons are collected only on winning boards and removed with winning memes. Collect two in one spin. On the first board without a win, the charge refreshes the entire board while keeping the multiplier. Only one reconnect per spin. Folders count only on the final board. The board stops refreshing at the 12th display or the payout cap.",
  "Таблица выплат от общей ставки, до множителя": "Paytable as multiples of the total bet, before the multiplier",
  "WILD заменяет обычные символы, на линии платится только лучшая комбинация. Пересекающиеся линии оплачиваются отдельно. Значок сети и папка сами не оплачиваются. Максимум всего раунда: 3 000 ставок. При достижении лимита остаток бонуса завершается. При ограничении последняя линия может оплачиваться частично.": "WILD substitutes for regular symbols. Only the best combination on each line pays. Overlapping lines pay separately. Network icons and folders do not pay on their own. The round cap is 3,000 times the bet. Reaching it ends any remaining bonus spins. The final line may pay partially when capped.",
  "Одна ставка и одна итоговая выплата на раунд. При обрыве связи подтверждается прежний ход. Закрытие или скрытие окна останавливает авто. Вирусный режим сохраняется. Авто делает выбранные 10, 25 или 50 платных вращений и останавливается при входе в бонус. Покупки бонуса нет.": "One bet and one final payout per round. A lost connection retries the existing action. Closing or hiding the window stops autoplay. Viral mode is saved. Autoplay runs the selected 10, 25 or 50 paid spins and stops when a bonus starts. No bonus buy is available.",
  "Оценка долгосрочного возврата: около 96,2% от суммы ставок, включая бонусы. Это среднее на длинной серии, а не обещание результата отдельного вращения.": "Estimated long-term return: about 96.2% of total bets, including bonuses. This is a long-run average, not a promised result for any individual spin.",
  "Все исходы определяет сервер. Только тестовые монеты клуба. Закрытие окна не отменяет принятую ставку.": "All outcomes are determined by the server. Club test coins only. Closing the window does not cancel an accepted bet.",
  "Мемные реакции": "Meme reactions",
  "Настоящие мемные звуки": "Original meme sounds",
